referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  if (d.mode === "deserialize") {
    let result = JSON.parse(JSON.stringify(d.json));
    for (const [p, type] of d.meta) {
      if (p.length === 0) {
        result = { $type: type, value: result };
        continue;
      }
      let n = result;
      for (const k of p.slice(0, -1)) n = n[k];
      const k = p.at(-1);
      n[k] = { $type: type, value: n[k] };
    }
    return result;
  }
  const meta = [];
  const visit = (v, p) => {
    if (v && typeof v === "object" && !Array.isArray(v) && Object.hasOwn(v, "$type")) {
      meta.push([p, v.$type]);
      return v.value;
    }
    if (Array.isArray(v)) return v.map((x, i) => visit(x, p.concat(String(i))));
    if (v && typeof v === "object")
      return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, visit(x, p.concat(k))]));
    return v;
  };
  return { json: visit(d.value, []), meta };
}

